package com.twelvemonkeys.imageio.plugins.pcx;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.ByteBuffer;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

class RLEDecoderTest {

    private final RLEDecoder decoder = new RLEDecoder();

    @Test
    void decodesLiteralBytes() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0x01, 0x02, 0x7F), buffer);

        assertEquals(3, position);
        assertArrayEquals(new byte[]{0x01, 0x02, 0x7F}, contents(buffer, 3));
    }

    @Test
    void decodesCompressedRun() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0xC3, 0x2A), buffer);

        assertEquals(3, position);
        assertArrayEquals(new byte[]{0x2A, 0x2A, 0x2A}, contents(buffer, 3));
    }

    @Test
    void decodesZeroLengthRun() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0xC0, 0x55), buffer);

        assertEquals(0, position);
    }

    @Test
    void decodesMaximumLengthRun() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0xFF, 0x77), buffer);

        assertEquals(63, position);
        byte[] expected = new byte[63];
        java.util.Arrays.fill(expected, (byte) 0x77);
        assertArrayEquals(expected, contents(buffer, 63));
    }

    @Test
    void decodesLiteralWithHighBitSet() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0x80, 0xBF), buffer);

        assertEquals(2, position);
        assertArrayEquals(new byte[]{(byte) 0x80, (byte) 0xBF}, contents(buffer, 2));
    }

    @Test
    void stopsAtEndOfInput() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(), buffer);

        assertEquals(0, position);
    }

    @Test
    void stopsWhenRunMarkerIsNotFollowedByValue() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);

        int position = decoder.decode(stream(0xC5), buffer);

        assertEquals(0, position);
    }

    @Test
    void doesNotConsumeInputWhenLessThan64BytesRemain() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(64);
        buffer.position(1); // 63 bytes remaining

        int position = decoder.decode(stream(0xC1, 0x11), buffer);

        assertEquals(1, position);
    }

    @Test
    void decodesAtMost64BytesPerCall() throws IOException {
        byte[] literals = new byte[65];
        for (int i = 0; i < literals.length; i++) {
            literals[i] = (byte) (i + 1);
        }

        ByteBuffer first = ByteBuffer.allocate(64);
        int firstPosition = decoder.decode(stream(literals), first);
        assertEquals(64, firstPosition);
        assertEquals(64, first.position());

        // The final literal is still pending and is returned by the next call.
        ByteBuffer second = ByteBuffer.allocate(64);
        int secondPosition = decoder.decode(stream(65), second);
        assertEquals(1, secondPosition);
        assertArrayEquals(new byte[]{65}, contents(second, 1));
    }

    private static ByteArrayInputStream stream(int... values) {
        byte[] bytes = new byte[values.length];
        for (int i = 0; i < values.length; i++) {
            bytes[i] = (byte) values[i];
        }
        return new ByteArrayInputStream(bytes);
    }

    private static byte[] contents(ByteBuffer buffer, int length) {
        byte[] result = new byte[length];
        System.arraycopy(buffer.array(), 0, result, 0, length);
        return result;
    }
}
