package com.twelvemonkeys.imageio.plugins.pcx;

import org.junit.jupiter.api.Test;
import org.w3c.dom.Node;

import javax.imageio.ImageReadParam;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataFormatImpl;
import java.awt.Rectangle;
import java.awt.color.ColorSpace;
import java.awt.image.BandedSampleModel;
import java.awt.image.BufferedImage;
import java.awt.image.IndexColorModel;
import java.io.IOException;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PCXImageReaderTest {

    @Test
    void readsUncompressedGrayscaleSamplesExactly() throws IOException {
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_NONE, 8, 4, 2,
                PCXTestSupport.blankPalette(), 1, 4);
        byte[] body = {
                0, 64, (byte) 128, (byte) 255,
                (byte) 255, (byte) 128, 64, 0
        };

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            assertEquals(4, reader.getWidth(0));
            assertEquals(2, reader.getHeight(0));
            assertEquals(1, reader.getNumImages(true));

            ImageTypeSpecifier rawType = reader.getRawImageType(0);
            assertEquals(ColorSpace.TYPE_GRAY, rawType.getColorModel().getColorSpace().getType());
            assertEquals(1, rawType.getNumBands());

            BufferedImage image = reader.read(0);
            assertEquals(4, image.getWidth());
            assertEquals(2, image.getHeight());
            assertArrayEquals(new int[]{0, 64, 128, 255}, rowSamples(image, 0));
            assertArrayEquals(new int[]{255, 128, 64, 0}, rowSamples(image, 1));
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void readsRleCompressedGrayscaleSamplesExactly() throws IOException {
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_RLE, 8, 4, 1,
                PCXTestSupport.blankPalette(), 1, 4);
        byte[] body = {(byte) 0xC3, 0x10, 0x20}; // 16, 16, 16, 32

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            BufferedImage image = reader.read(0);

            assertArrayEquals(new int[]{16, 16, 16, 32}, rowSamples(image, 0));
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void readsEightBitIndexedImageWithVgaPalette() throws IOException {
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_NONE, 8, 2, 1,
                PCXTestSupport.blankPalette(), 1, 2);

        byte[] body = new byte[2 + 1 + 768];
        body[0] = 1;
        body[1] = 2;
        body[2] = PCX.VGA_PALETTE_MAGIC;
        body[3] = 1;
        body[4] = 2;
        body[5] = 3;
        body[6] = 4;
        body[7] = 5;
        body[8] = 6;

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            ImageTypeSpecifier rawType = reader.getRawImageType(0);
            IndexColorModel model = assertInstanceOf(IndexColorModel.class, rawType.getColorModel());
            assertEquals(256, model.getMapSize());
            assertEquals(0xFF010203, model.getRGB(0));
            assertEquals(0xFF040506, model.getRGB(1));

            BufferedImage image = reader.read(0);
            assertEquals(1, image.getRaster().getSample(0, 0, 0));
            assertEquals(2, image.getRaster().getSample(1, 0, 0));
            assertEquals(0xFF010203, image.getRGB(0, 0));
            assertEquals(0xFF040506, image.getRGB(1, 0));
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void ignoresVgaPaletteIfMagicByteIsMissing() throws IOException {
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_NONE, 8, 2, 1,
                PCXTestSupport.blankPalette(), 1, 2);

        byte[] body = new byte[2 + 1 + 768];
        body[0] = 1;
        body[1] = 2;
        body[2] = 0x00; // not the VGA palette marker

        PCXImageReader reader = PCXTestSupport.reader(PCXTestSupport.pcx(header, body));
        try {
            ImageTypeSpecifier rawType = reader.getRawImageType(0);
            assertEquals(ColorSpace.TYPE_GRAY, rawType.getColorModel().getColorSpace().getType());
        }
        finally {
            PCXTestSupport.dispose(reader);
        }
    }

    @Test
    void readsThreePlaneRgbImageExactly() throws IOException {
        byte[] header = PCXTestSupport.header(5, PCX.COMPRESSION_NONE, 8, 2, 2,
                PCXTestSupport.blankPalette(), 3, 2);
        byte[] body = {
                10, 20, 30, 40, 50, 60, // R0, G0, B0
                70, 80, 90, 100, 110, 120 // R1, G1, B1
